<script setup lang="ts">
import {reactive,ref} from 'vue';import {useAuth} from '../stores/auth';import {api,message} from '../api';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';
const auth=useAuth(),router=useRouter(),form=reactive({currentPassword:'',newPassword:'',confirmation:''}),error=ref(''),busy=ref(false);
async function save(){error.value='';if(form.newPassword!==form.confirmation){error.value='两次输入的新密码不一致';return;}if(form.newPassword.length<12||!/[A-Za-z]/.test(form.newPassword)||!/[0-9]/.test(form.newPassword)){error.value='新密码至少12位，且包含字母和数字';return;}busy.value=true;try{await api.post('/auth/password',{currentPassword:form.currentPassword,newPassword:form.newPassword});auth.clear();ElMessage.success('密码已修改，请重新登录');router.push('/login');}catch(e){error.value=message(e);}finally{busy.value=false;}}
</script>
<template><div class="account-grid"><section class="panel"><div class="section-title"><h2>身份与授权</h2></div><el-descriptions :column="1" border><el-descriptions-item label="账号">{{auth.user?.username}}</el-descriptions-item><el-descriptions-item label="姓名">{{auth.user?.displayName}}</el-descriptions-item><el-descriptions-item label="所属主体">{{auth.user?.businessEntity.name}}</el-descriptions-item><el-descriptions-item label="业务角色">{{auth.user?.roles.map(r=>r.name).join('、')}}</el-descriptions-item><el-descriptions-item label="数据范围">{{auth.user?.businessEntity.type==='PLATFORM'?'按授权访问平台数据':'本企业及本企业参与的业务'}}</el-descriptions-item></el-descriptions></section><section class="panel"><div class="section-title"><h2>修改密码</h2></div><el-alert v-if="auth.user?.mustChangePassword" title="首次登录或密码已重置，请先设置新密码" type="warning" :closable="false"/><el-form label-position="top" @submit.prevent="save"><el-form-item label="原密码"><el-input v-model="form.currentPassword" type="password" show-password autocomplete="current-password" aria-label="原密码"/></el-form-item><el-form-item label="新密码"><el-input v-model="form.newPassword" type="password" show-password autocomplete="new-password" placeholder="至少12位，含字母和数字" aria-label="新密码"/></el-form-item><el-form-item label="确认新密码"><el-input v-model="form.confirmation" type="password" show-password autocomplete="new-password" aria-label="确认新密码"/></el-form-item><el-alert v-if="error" :title="error" type="error" :closable="false" class="form-error"/><el-button type="primary" native-type="submit" :loading="busy">保存新密码</el-button></el-form></section></div></template>
